// Strict input validation. Nothing here silently drops a lead: every
// item leaves this node with valid=true or valid=false plus a reason,
// and the IF node below routes both outcomes to somewhere recorded.
const body = $json.body || {};

function isNonEmptyString(v) {
  return typeof v === 'string' && v.trim().length > 0;
}

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
// Documented shape: optional leading '+', then 7-20 characters drawn from
// digits/spaces/parentheses/hyphens/dots, with AT LEAST ONE digit somewhere
// in the string. This is a character-whitelist shape check, not phone-
// number-syntax validation -- it rejects punctuation-only input like
// '-------' that the whitelist alone would let through.
const PHONE_RE = /^(?=.*[0-9])\+?[0-9()\-.\s]{7,20}$/;

const reasons = [];

// name: required, string, non-empty after trim, sane max length
if (!isNonEmptyString(body.name)) {
  reasons.push('name_missing_or_invalid_type');
} else if (body.name.trim().length > 200) {
  reasons.push('name_too_long');
}

// email: required, must be a string, must match a real email shape
if (typeof body.email !== 'string' || body.email.trim().length === 0) {
  reasons.push('email_missing_or_invalid_type');
} else if (!EMAIL_RE.test(body.email.trim())) {
  reasons.push('email_format_invalid');
}

// company: required, string, non-empty
if (!isNonEmptyString(body.company)) {
  reasons.push('company_missing_or_invalid_type');
} else if (body.company.trim().length > 200) {
  reasons.push('company_too_long');
}

// phone: optional, but if present must be a string matching the documented
// digit-bearing shape above (not full phone-number validation)
if (body.phone !== undefined && body.phone !== null && body.phone !== '') {
  if (typeof body.phone !== 'string' || !PHONE_RE.test(body.phone.trim())) {
    reasons.push('phone_invalid_type_or_format');
  }
}

// message: optional, but if present must be a string within a sane length
if (body.message !== undefined && body.message !== null && body.message !== '') {
  if (typeof body.message !== 'string') {
    reasons.push('message_invalid_type');
  } else if (body.message.length > 5000) {
    reasons.push('message_too_long');
  }
}

// lead_id: required, string, non-empty -- the source system's own id,
// used as the idempotency/dedup key alongside email
if (!isNonEmptyString(body.lead_id)) {
  reasons.push('lead_id_missing_or_invalid_type');
}

const valid = reasons.length === 0;

return {
  json: {
    valid,
    reasons,
    lead_id: isNonEmptyString(body.lead_id) ? body.lead_id.trim() : null,
    name: isNonEmptyString(body.name) ? body.name.trim() : null,
    email: typeof body.email === 'string' ? body.email.trim().toLowerCase() : null,
    company: isNonEmptyString(body.company) ? body.company.trim() : null,
    phone: typeof body.phone === 'string' && body.phone.trim() ? body.phone.trim() : null,
    message: typeof body.message === 'string' ? body.message : null,
    received_at: new Date().toISOString()
  }
};

// Orchestrates enrichment then CRM upsert for one validated lead, with
// manual retry and exponential backoff on each external call. A
// persistent TRANSPORT failure at either stage never drops the lead
// silently -- it is returned with status='dead_lettered', the failing
// stage, and the last error, so the branch below records it as a
// dead-letter row.
//
// A malformed HTTP 200 (missing the fields this pipeline actually
// depends on) is validated separately from transport failure and is
// NOT retried -- retrying a response-validation failure risks repeating
// a write that may already have committed upstream. It is returned as
// its own dead_lettered stage instead, distinct from a transport error.
//
// Ambiguous CRM outcomes -- transport retries exhausted, or a malformed
// 200 -- may still have committed upstream. Before classifying them the
// node reconciles by idempotency key (GET /contacts/lookup): found ->
// the write committed, reconcile to 'accepted'; confirmed absent ->
// 'dead_lettered'; lookup itself failed -> 'outcome_unknown', recorded
// separately and never counted as a failed intake.
//
// A well-formed 200 whose contact is a DIFFERENT lead (lead_id/email not
// the ones submitted) does not by itself prove nothing was written under
// this lead's own idempotency key -- the ack, not the write, may be the
// corrupted part. It is reconciled the same way as any other ambiguous
// CRM outcome: confirmed absent under our key -> dead_lettered; found
// with OUR identity -> accepted; found but still identity-mismatched, or
// the reconciliation lookup itself fails -> outcome_unknown, recorded
// separately, never accepted or notified.
const lead = $json;
const ENRICH_URL = $env.ENRICH_URL;
const CRM_URL = $env.CRM_URL;

// Stable idempotency key derived from the lead's own id (required and
// validated upstream in Validate Lead). A transport retry of the CRM
// upsert -- request sent, reply lost -- replays under the SAME key, so
// the mock CRM can recognize it as the same logical write instead of a
// new one and avoid a second upsert_count increment.
const idempotencyKey = `lead-${lead.lead_id}`;

async function withRetry(fn, maxAttempts, baseDelayMs) {
  let lastError = null;
  let attempts = 0;
  let delay = baseDelayMs;
  while (attempts < maxAttempts) {
    attempts += 1;
    try {
      const result = await fn();
      return { ok: true, result, attempts };
    } catch (err) {
      lastError = (err && err.message) ? err.message : String(err);
      if (attempts < maxAttempts) {
        await new Promise((resolve) => setTimeout(resolve, delay));
        delay *= 2; // exponential backoff: 200ms, 400ms, ...
      }
    }
  }
  return { ok: false, error: lastError, attempts };
}

function isValidEnrichment(e) {
  return !!e && typeof e === 'object' &&
    typeof e.industry === 'string' && e.industry.trim().length > 0 &&
    typeof e.company_size === 'string' && e.company_size.trim().length > 0 &&
    typeof e.fit_score === 'number' && Number.isFinite(e.fit_score);
}

function isWellFormedCrmContact(r) {
  return !!r && typeof r === 'object' && r.status === 'ok' &&
    !!r.contact && typeof r.contact === 'object' &&
    typeof r.contact.email === 'string' && r.contact.email.trim().length > 0;
}

// Identity binding: the contact returned must be the lead we submitted.
function isValidCrmContact(contact) {
  return !!contact && typeof contact === 'object' &&
    contact.lead_id === lead.lead_id &&
    typeof contact.email === 'string' &&
    contact.email.trim().toLowerCase() === lead.email;
}

// Reconcile an ambiguous CRM outcome against the CRM's own record of
// committed idempotency keys.
async function reconcile(stage, reason, attempts) {
  const lookup = await withRetry(
    () => this.helpers.httpRequest({
      method: 'GET',
      url: `${CRM_URL}/contacts/lookup?idempotency_key=${encodeURIComponent(idempotencyKey)}`,
      json: true,
      timeout: 2000
    }),
    2,
    200
  );
  const r = lookup.ok ? lookup.result : null;
  if (!r || typeof r !== 'object' || typeof r.found !== 'boolean' ||
      (r.found && !isWellFormedCrmContact({ status: 'ok', contact: r.contact }))) {
    return {
      json: {
        ...lead,
        enrichment,
        status: 'outcome_unknown',
        stage,
        reason: `${reason}; reconciliation lookup failed: ${lookup.ok ? 'malformed lookup response' : lookup.error}`,
        attempts
      }
    };
  }
  if (r.found) {
    if (!isValidCrmContact(r.contact)) {
      // A record exists under OUR OWN idempotency key, but its identity
      // does not match this lead -- wrong identity cannot prove
      // non-commit. Not a plain failure (something is written under our
      // key) and not a trustworthy accept either (we cannot bind it to
      // this lead). Recorded as its own unknown outcome, never dead
      // -lettered and never accepted/notified.
      return {
        json: {
          ...lead,
          enrichment,
          crm_contact_rejected: r.contact,
          status: 'outcome_unknown',
          stage,
          reason: `${reason}; reconciliation lookup found a record under this lead's own idempotency key but its identity does not match the submitted lead (crm_response_identity_mismatch)`,
          attempts
        }
      };
    }
    return {
      json: { ...lead, enrichment, crm_contact: r.contact, status: 'accepted', reconciled: true }
    };
  }
  return {
    json: { ...lead, enrichment, status: 'dead_lettered', stage, reason, attempts }
  };
}

const enrichRes = await withRetry(
  () => this.helpers.httpRequest({
    method: 'POST',
    url: `${ENRICH_URL}/enrich`,
    body: { email: lead.email, company: lead.company },
    json: true,
    timeout: 2000
  }),
  3,
  200
);

if (!enrichRes.ok) {
  return {
    json: {
      ...lead,
      status: 'dead_lettered',
      stage: 'enrichment',
      reason: enrichRes.error,
      attempts: enrichRes.attempts
    }
  };
}

const enrichment = enrichRes.result;

if (!isValidEnrichment(enrichment)) {
  return {
    json: {
      ...lead,
      enrichment,
      status: 'dead_lettered',
      stage: 'enrichment_response_invalid',
      reason: 'enrichment response missing required fields (industry, company_size, fit_score)',
      attempts: enrichRes.attempts
    }
  };
}

const crmRes = await withRetry(
  () => this.helpers.httpRequest({
    method: 'POST',
    url: `${CRM_URL}/contacts`,
    body: {
      email: lead.email,
      name: lead.name,
      company: lead.company,
      phone: lead.phone,
      message: lead.message,
      lead_id: lead.lead_id,
      idempotency_key: idempotencyKey,
      enrichment
    },
    json: true,
    timeout: 2000
  }),
  3,
  200
);

if (!crmRes.ok) {
  return await reconcile.call(this, 'crm_upsert', crmRes.error, crmRes.attempts);
}

if (!isWellFormedCrmContact(crmRes.result)) {
  return await reconcile.call(this, 'crm_response_invalid',
    'CRM response missing status=ok or contact.email', crmRes.attempts);
}

if (!isValidCrmContact(crmRes.result.contact)) {
  // A well-formed 200 for the wrong contact does not prove nothing was
  // written under our idempotency key -- the ack, not the write, may be
  // the corrupted part. Reconcile it the same way as any other
  // ambiguous CRM outcome instead of trusting the mismatch either way.
  return await reconcile.call(this, 'crm_response_identity_mismatch',
    'CRM response identity mismatch: response contact lead_id/email do not match the submitted lead',
    crmRes.attempts);
}

return {
  json: {
    ...lead,
    enrichment,
    crm_contact: crmRes.result.contact,
    status: 'accepted'
  }
};
